import {
  createContext,
  lazy,
  Suspense,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useReducer,
  useState,
  type ReactNode,
} from "react";
import MuiThemeProvider from "@mui/material/styles/ThemeProviderNoVars";
import createTheme from "@mui/material/styles/createThemeNoVars";
import { todoReducer } from "../reducers/todoReducer";
import { AppStatus, PriorityType, Todo } from "../types/todo.types";

type ThemeMode = "light" | "dark";

interface ThemeContextType {
  theme: ThemeMode;
  setTheme: (t: ThemeMode) => void;
  todos: Todo[];
  isFetching: boolean;
  appStatus: AppStatus;
  addTodo: (title: string, priority: PriorityType) => Promise<void>;
  toggleTodo: (id: string) => Promise<void>;
  deleteTodo: (id: string) => Promise<void>;
  editTodo: (id: string, title: string, priority: PriorityType) => Promise<void>;
}

interface ThemeColors {
  primary: string;
  primaryDark: string;
  primaryLight: string;
  background: string;
  surface: string;
  textPrimary: string;
  textSecondary: string;
  border: string;
  borderStrong: string;
  error: string;
  success: string;
  warning: string;
  hover: string;
  selected: string;
  disabled: string;
  disabledBackground: string;
  selectedHover: string;
}

