const appThemes: Record<ThemeMode, ReturnType<typeof createTheme>> = {
  light: createAppTheme("light"),
  dark: createAppTheme("dark"),
};

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);
const AppStatusFeedback = lazy(() => import("../components/AppStatusFeedback"));

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<ThemeMode>(() => {
    const savedTheme = window.localStorage.getItem("theme");

    if (savedTheme === "light" || savedTheme === "dark") {
      return savedTheme;
    }

    return window.matchMedia("(prefers-color-scheme: dark)").matches
      ? "dark"
      : "light";
  });

  const [todos, dispatch] = useReducer(todoReducer, initialTodos);
  const isFetching = false;
  const [appStatus, setAppStatus] = useState<AppStatus>(idleStatus);

  const simulateNetworkDelay = useCallback((shouldFail = false) => {
    return new Promise<void>((resolve, reject) => {
      setTimeout(() => {
        if (shouldFail) {
          reject(new Error("Network Error"));
          return;
        }

        resolve();
      }, 600);
    });
  }, []);

  const setLoadingStatus = useCallback((message: string) => {
    setAppStatus({ type: "loading", message });
  }, []);

  const setSuccessStatus = useCallback((message: string) => {
    setAppStatus({ type: "success", message });
  }, []);

  const setErrorStatus = useCallback((message: string) => {
    setAppStatus({ type: "error", message });
  }, []);

  const handleCloseStatus = useCallback(() => {
    setAppStatus((currentStatus) =>
      currentStatus.type === "loading" ? currentStatus : idleStatus,
    );
  }, []);

  const muiTheme = appThemes[theme];

  useEffect(() => {
    document.documentElement.classList.toggle("dark", theme === "dark");
    document.documentElement.style.colorScheme = theme;
    window.localStorage.setItem("theme", theme);
  }, [theme]);

  const value = useMemo<ThemeContextType>(() => ({
    theme,
    setTheme,
    todos,
    isFetching,
    appStatus,
    addTodo: async (title, priority) => {
      setLoadingStatus("Dodawanie zadania...");

      try {
        const isError = title.toLowerCase().includes("error");
        await simulateNetworkDelay(isError);
        dispatch({ type: "ADD", payload: { title, priority } });
        setSuccessStatus("Zadanie dodane pomyslnie!");
      } catch (err) {
        setErrorStatus("Wystapil blad podczas dodawania zadania.");
        throw err;
      }
    },
    toggleTodo: async (id) => {
      setLoadingStatus("Aktualizowanie statusu zadania...");

      try {
        await simulateNetworkDelay();
        dispatch({ type: "TOGGLE", payload: id });
        setSuccessStatus("Status zadania zostal zaktualizowany.");
      } catch {
        setErrorStatus("Nie udalo sie zaktualizowac statusu.");
      }
    },
    deleteTodo: async (id) => {
      setLoadingStatus("Usuwanie zadania...");

      try {
        await simulateNetworkDelay();
        dispatch({ type: "DELETE", payload: id });
        setSuccessStatus("Zadanie zostalo usuniete.");
      } catch {
        setErrorStatus("Nie udalo sie usunac zadania.");
      }
    },
    editTodo: async (id, title, priority) => {
      setLoadingStatus("Zapisywanie zmian...");

      try {
        const isError = title.toLowerCase().includes("error");
        await simulateNetworkDelay(isError);
        dispatch({ type: "EDIT", payload: { id, title, priority } });
        setSuccessStatus("Zadanie zapisane pomyslnie!");
      } catch (err) {
        setErrorStatus("Wystapil blad podczas zapisywania zadania.");
        throw err;
      }
    },
  }), [
    appStatus,
    isFetching,
    setErrorStatus,
    setLoadingStatus,
    setSuccessStatus,
    simulateNetworkDelay,
    theme,
    todos,
  ]);

  const isStatusOpen = appStatus.type !== "idle" && Boolean(appStatus.message);

  return (
    <MuiThemeProvider theme={muiTheme}>
      <ThemeContext.Provider value={value}>
        {children}
      </ThemeContext.Provider>
      {isStatusOpen ? (
        <Suspense fallback={null}>
          <AppStatusFeedback status={appStatus} onClose={handleCloseStatus} />
        </Suspense>
      ) : null}
    </MuiThemeProvider>
  );
}

export function useTheme() {
  const ctx = useContext(ThemeContext);

  if (!ctx) {
    throw new Error("useTheme must be used within a ThemeProvider");
  }

  return ctx;
}

export function useTodoContext() {
  const ctx = useContext(ThemeContext);

  if (!ctx) {
    throw new Error("useTodoContext must be used within a ThemeProvider");
  }

  return ctx;
}
